import{_ as t,o,c as a,a0 as i}from"./chunks/framework.Dx25mwie.js";const h=JSON.parse('{"title":"SCALE LXP Data Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"policies/data-privacy-policy.md","filePath":"policies/data-privacy-policy.md"}'),r={name:"policies/data-privacy-policy.md"};function n(s,e,l,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="scale-lxp-data-privacy-policy" tabindex="-1">SCALE LXP Data Privacy Policy <a class="header-anchor" href="#scale-lxp-data-privacy-policy" aria-label="Permalink to &quot;SCALE LXP Data Privacy Policy&quot;">​</a></h1><p><strong>Document owner:</strong> Privacy / Product Leadership<br><strong>Approved by:</strong> [Insert approver]<br><strong>Effective date:</strong> [Insert date]<br><strong>Review cadence:</strong> At least annually and upon material changes to data practices, vendors, or regulatory obligations<br><strong>Applies to:</strong> Individuals who use SCALE LXP as instructors, students, or institutional contacts, and to institutions that deploy SCALE LXP in educational settings</p><h2 id="_1-purpose" tabindex="-1">1. Purpose <a class="header-anchor" href="#_1-purpose" aria-label="Permalink to &quot;1. Purpose&quot;">​</a></h2><p>This Data Privacy Policy describes how SCALE LXP collects, uses, stores, and shares personal information when you use our classroom supply chain simulation platform. SCALE LXP is designed for college-level instruction; it helps instructors run scenarios, collect student submissions, generate simulation outcomes with AI assistance, and display dashboards and leaderboards.</p><p>If you are accessing SCALE LXP through a school or employer, your institution may have additional notices or agreements that apply alongside this policy.</p><h2 id="_2-personal-information-we-collect" tabindex="-1">2. Personal information we collect <a class="header-anchor" href="#_2-personal-information-we-collect" aria-label="Permalink to &quot;2. Personal information we collect&quot;">​</a></h2><p>SCALE LXP collects <strong>only</strong> the following categories of personal information about users:</p><table tabindex="0"><thead><tr><th>Category</th><th>Examples</th><th>Why we collect it</th></tr></thead><tbody><tr><td><strong>Contact and identity</strong></td><td>Email address, full name</td><td>Account creation, sign-in, communications about the service, and displaying identity in the product (for example, roster and dashboards).</td></tr><tr><td><strong>Student identifier</strong></td><td>Student ID (as provided by your institution or you)</td><td>Linking your account to class enrollment and instructional records practices required by your institution.</td></tr></tbody></table><p>We do <strong>not</strong> use SCALE LXP to collect government identification numbers, payment card data, health information, precise geolocation, or biometric data as part of the core product.</p><h3 id="simulation-and-gameplay-data" tabindex="-1">Simulation and gameplay data <a class="header-anchor" href="#simulation-and-gameplay-data" aria-label="Permalink to &quot;Simulation and gameplay data&quot;">​</a></h3><p>Decisions, ledger entries, scores, narratives, and other outputs produced inside the simulation are <strong>educational and fictitious</strong> for learning purposes. They are not intended to represent real financial, employment, or legal facts about you. We still treat account-related records (including simulation records tied to your account) as operational data that must be protected, as described in this policy.</p><h3 id="information-we-collect-automatically" tabindex="-1">Information we collect automatically <a class="header-anchor" href="#information-we-collect-automatically" aria-label="Permalink to &quot;Information we collect automatically&quot;">​</a></h3><p>Like most web applications, our systems may generate <strong>technical and security information</strong> when you use the service, such as IP addresses, device and browser type, timestamps, and diagnostic logs. We use this information to operate the service, secure our systems, troubleshoot issues, and understand aggregate usage. We do not sell your personal information.</p><h3 id="information-from-third-parties" tabindex="-1">Information from third parties <a class="header-anchor" href="#information-from-third-parties" aria-label="Permalink to &quot;Information from third parties&quot;">​</a></h3><p>If you sign in through an identity provider (for example, single sign-on offered by your institution) or we receive roster or enrollment information from your school, we may receive name, email, student identifier, or role information consistent with what your institution chooses to share for educational use.</p><h2 id="_3-how-we-use-personal-information" tabindex="-1">3. How we use personal information <a class="header-anchor" href="#_3-how-we-use-personal-information" aria-label="Permalink to &quot;3. How we use personal information&quot;">​</a></h2><p>We use personal information to:</p><ul><li>Create and maintain accounts and sessions.</li><li>Associate you with the correct classes, roles (instructor or student), and permissions.</li><li>Send service-related email where enabled (for example, transactional notices through our email provider).</li><li>Run the simulation, store submissions and outcomes linked to your account for instructional purposes, and display results to authorized users (for example, instructors viewing class progress).</li><li>Protect the security and integrity of the platform, enforce our terms, and comply with law.</li></ul><p>We use AI services to generate structured simulation outputs from scenario inputs. <strong>Prompts for AI processing are not permanently stored as a product feature</strong>; however, vendors may apply their own retention or logging consistent with their terms and our configuration.</p><h2 id="_4-legal-bases-where-applicable" tabindex="-1">4. Legal bases (where applicable) <a class="header-anchor" href="#_4-legal-bases-where-applicable" aria-label="Permalink to &quot;4. Legal bases (where applicable)&quot;">​</a></h2><p>Depending on your location, we may rely on one or more of the following bases to process personal information:</p><ul><li><strong>Performance of a contract</strong> with you or your institution.</li><li><strong>Legitimate interests</strong> in operating, securing, and improving the service, consistent with your privacy rights.</li><li><strong>Consent</strong> where required for specific communications or optional features.</li><li><strong>Legal obligation</strong> where we must retain or disclose information to comply with applicable law.</li></ul><p>Your institution may act as an independent controller for certain student records; in those cases, refer to your school’s privacy notice as well.</p><h2 id="_5-how-we-share-personal-information" tabindex="-1">5. How we share personal information <a class="header-anchor" href="#_5-how-we-share-personal-information" aria-label="Permalink to &quot;5. How we share personal information&quot;">​</a></h2><p>We share personal information only with:</p><ul><li><strong>Service providers</strong> that help us run SCALE LXP under contractual obligations, including—for example—authentication (such as Clerk), database hosting, cloud infrastructure, email delivery (such as SendGrid), and AI inference (such as OpenAI), each according to their role and our agreements.</li><li><strong>Your institution</strong>, where applicable, through normal course administration (for example, instructors viewing class data).</li><li><strong>Authorities or third parties</strong> when required by law, court order, or to protect rights, safety, or security.</li></ul><p>We do not sell personal information as defined under U.S. state privacy laws that use that term.</p><h2 id="_6-international-transfers" tabindex="-1">6. International transfers <a class="header-anchor" href="#_6-international-transfers" aria-label="Permalink to &quot;6. International transfers&quot;">​</a></h2><p>If you access SCALE LXP from outside the country where our systems or vendors process data, your information may be transferred across borders. Where required, we use appropriate safeguards such as standard contractual clauses or vendor commitments consistent with applicable law.</p><h2 id="_7-retention" tabindex="-1">7. Retention <a class="header-anchor" href="#_7-retention" aria-label="Permalink to &quot;7. Retention&quot;">​</a></h2><p>We retain personal information for as long as needed to provide the service, meet instructional and institutional needs, resolve disputes, enforce agreements, and comply with legal obligations. Simulation records tied to your account may be retained for the life of the class or longer where required by your institution’s policies or our agreements with them. Technical logs may be retained for shorter periods according to security and operational needs.</p><p>When information is no longer needed, we delete or de-identify it in line with our retention practices and technical capabilities.</p><h2 id="_8-security" tabindex="-1">8. Security <a class="header-anchor" href="#_8-security" aria-label="Permalink to &quot;8. Security&quot;">​</a></h2><p>We implement administrative, technical, and organizational measures designed to protect personal information against unauthorized access, loss, or alteration. No method of transmission or storage is completely secure; we encourage users to use strong passwords and institutional SSO where available.</p><p>Additional detail about how SCALE LXP approaches security may be found in related documentation provided to institutions (for example, information security materials shared during procurement).</p><h2 id="_9-your-choices-and-rights" tabindex="-1">9. Your choices and rights <a class="header-anchor" href="#_9-your-choices-and-rights" aria-label="Permalink to &quot;9. Your choices and rights&quot;">​</a></h2><p>Depending on your jurisdiction, you may have rights to:</p><ul><li>Access or receive a copy of certain personal information.</li><li>Correct inaccurate information.</li><li>Delete certain information, subject to instructional records and legal exceptions.</li><li>Object to or restrict certain processing.</li><li>Withdraw consent where processing is consent-based.</li><li>Appeal decisions regarding privacy requests where applicable.</li></ul><p>To exercise rights, contact us using the information in Section 11. We may need to verify your identity and coordinate with your institution when records are jointly controlled or maintained for academic purposes.</p><p>You may also control certain communications through account settings or by unsubscribing from non-essential messages where offered.</p><h2 id="_10-children-and-students" tabindex="-1">10. Children and students <a class="header-anchor" href="#_10-children-and-students" aria-label="Permalink to &quot;10. Children and students&quot;">​</a></h2><p>SCALE LXP is intended for use in higher education contexts. If you believe we have collected personal information from a minor in a manner inconsistent with applicable law, contact us and we will take appropriate steps.</p><h2 id="_11-contact" tabindex="-1">11. Contact <a class="header-anchor" href="#_11-contact" aria-label="Permalink to &quot;11. Contact&quot;">​</a></h2><p>For privacy questions or requests regarding this policy:</p><p><strong>Email:</strong> [Insert privacy contact email]<br><strong>Postal address:</strong> [Insert legal entity name and address]</p><p>If you are covered by your institution’s agreement with SCALE LXP, your school’s data protection or IT office may also assist with requests.</p><h2 id="_12-changes-to-this-policy" tabindex="-1">12. Changes to this policy <a class="header-anchor" href="#_12-changes-to-this-policy" aria-label="Permalink to &quot;12. Changes to this policy&quot;">​</a></h2><p>We may update this Data Privacy Policy from time to time. We will post the revised policy and update the effective date. If changes are material, we will provide additional notice as appropriate (for example, by email or in-product notice).</p><hr><p><em>This document is provided for transparency and institutional review. It is not legal advice; consult qualified counsel for compliance with specific laws or contracts.</em></p>',50)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
